/// A message the kernel raises and the shell shows.
///
/// The kernel decides which message a state calls for and carries the number.
/// It never carries the words: a string that exists to be read has no reason
/// to sit in the kernel's memory, and the shell has the locale files already
/// (apps/web/src/locale) — the same split `strerror` is on the other side of.
///
/// The number is the name here. A band is what a message is about, and a
/// message keeps its number for as long as anything can be holding one: an
/// old shell reads a number a new kernel sends, so a number that has meant
/// something must never come to mean another thing. Retire one by leaving
/// the gap.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u32)]
pub enum Message {
    // ---- 0x02 where the device says it is ----
    GeolocationUnsupported = 0x0203,
    GeolocationPermissionDenied = 0x0204,
    GeolocationPositionUnavailable = 0x0205,
    GeolocationTimeout = 0x0206,
    GeolocationGenericError = 0x0207,

    // ---- 0x03 which way the device is facing ----
    OrientationPermissionError = 0x0302,
    OrientationPermissionDenied = 0x0303,
    OrientationSignalLost = 0x0304,
}

impl Message {
    pub const ALL: [Message; 8] = [
        Message::GeolocationUnsupported,
        Message::GeolocationPermissionDenied,
        Message::GeolocationPositionUnavailable,
        Message::GeolocationTimeout,
        Message::GeolocationGenericError,
        Message::OrientationPermissionError,
        Message::OrientationPermissionDenied,
        Message::OrientationSignalLost,
    ];

    /// The member a number names, or none for a number nobody gave out.
    pub fn of(number: u32) -> Option<Message> {
        Message::ALL.into_iter().find(|m| *m as u32 == number)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u32)]
pub enum Command {
    // ---- the process asks the host: its system calls, raised on the completion ring and run before the next turn (the rest are the host stream's records, host.json) ----
    /// Start watching.
    SENSOR_START = 0x1201,
    /// Stop watching.
    SENSOR_STOP = 0x1203,

    // ---- the host answers: an I/O the process started, done ----
    /// An image the kernel asked decoded (host.json's IMAGE_DECODE): 0, held for the renderer
    /// as the kernel's `image`, or -errno where the file is not an image the device decodes.
    /// A file that did not come is the open's answer (xpute's SYS_OPENED), not this.
    IMAGE_DECODED = 0x1301,
    /// A GPS fix; a field is absent where the browser gave none.
    SENSOR_POSITION = 0x1202,
    /// An orientation event; a field is absent where the browser gave none.
    SENSOR_ORIENTATION = 0x1205,
    /// The watch failed and was stopped.
    SENSOR_ERROR = 0x1204,
    /// The compass failed and its listener was removed, where the platform says so.
    SENSOR_ORIENTATION_LOST = 0x120a,

    // ---- the host tells the process: its start, its turn, its window, its devices and its input ----
    /// The kernel's start: what the platform is, and what it was handed to start with.
    WORLD_BOOT = 0x1001,
    /// The frame of the turn the doorbell's quota rang in: the effects' turn, then the tick's
    /// phases on what is left of the quota, the fetches within the credits. The turn leaves
    /// its signals on the completion ring, drawn by the kernel.
    WORLD_FRAME = 0x1002,
    /// The tab's visibility; the host rings the doorbell for it at once, since a hidden
    /// page gets no frame and hiding is the save's last sure moment.
    WORLD_VISIBILITY = 0x1003,
    /// What the tile source declares of itself, once the shell has it (published.json's
    /// SOURCE, or the dev tile server's answer in the same form). Until it comes nothing is
    /// observed: the floor is held at the zoom it names, and no view is drawn from a
    /// zoom the source does not supply whole.
    WORLD_SOURCE = 0x1005,
    /// A permission as the shell's prompt or the browser's change reported it.
    SENSOR_PERMISSION = 0x1206,
    /// The canvas's client rect.
    INPUT_RECT = 0x1101,
    /// A pointer event on the canvas, in client pixels.
    INPUT_POINTER = 0x1102,
    /// What the pointer holds, sent when it changes: the tool, the cube or decor a placing tool takes, and the object size tier. The kernel keeps a cube and a decor apart, so choosing another tool forgets neither, and picks again under a hovering pointer.
    INPUT_HOLD = 0x110b,
    INPUT_WHEEL = 0x1103,
    /// The screen direction the held movement keys point, sent when it changes: each axis -1, 0 or 1, x to the right and y down.
    INPUT_KEYS = 0x1106,
    /// A device answered; the kernel's renderer is made on it (crates/pxl/web/render/src/gpu/renderer.rs).
    GPU_READY = 0x1401,
    /// The device went away, and every object on it.
    GPU_LOST = 0x1402,

    // ---- the shell and the process: what the UI asks of it, and what it shows the UI ----
    /// A call, answered with the surface's handle, 0 refused: a canvas the shell hands over, drawn by the kernel alone from then on.
    SURFACE_OPEN = 0x1501,
    /// The canvas's layout box in device pixels, transforms aside; the buffer it is drawn into is the kernel's.
    SURFACE_RESIZE = 0x1502,
    /// A call: the canvas is going, and what it held on the device is let go before the call returns.
    SURFACE_CLOSE = 0x1503,
    /// A character drawn alone into a surface the shell handed over, as the picker shows it.
    PREVIEW_OPEN = 0x1801,
    PREVIEW_CLOSE = 0x1802,
    /// A setting set from the sheet or the character picker.
    SETTING_SET = 0x1601,
    /// A line the player said, shown over the character.
    CHAT_SEND = 0x1701,
    /// The tracking button's press, as the button showed it.
    INPUT_TRACKING = 0x1104,
    /// Where the camera stands, set outright rather than driven: what the kernel's own
    /// test puts a view at, and what an A/B reads two builds at the same view with.
    INPUT_VIEW = 0x1105,
    /// The compass's press: north up.
    INPUT_COMPASS_RESET = 0x1107,
    /// A search result: the map center moved there.
    INPUT_GO_TO = 0x1108,
    /// A tracked pose: where a tracker has the camera, and its turn as a unit quaternion
    /// (x, y, z, w) from the camera's axes to the tracker's, in the world's units. The
    /// first of a run is taken to be where the camera already is, so nothing moves as
    /// it begins; the camera follows the tracker from there until POSE_END.
    INPUT_POSE = 0x1109,
    /// The tracker let the camera go: back to the controller it had.
    INPUT_POSE_END = 0x110a,
    /// The map is on screen and wants the sensors.
    SENSOR_OPEN = 0x1208,
    /// The map is gone, and the sensors are let go.
    SENSOR_CLOSE = 0x1209,
    /// The search panel's location card: the location asked for. The compass is asked for
    /// where it is used, entering follow mode (TRACKING), and never alone: nothing reads it
    /// without the location.
    SENSOR_ENABLE_LOCATION = 0x1207,
    /// A fresh recording window.
    PROFILER_START = 0x1901,
    /// The window frozen, so what is exported holds still.
    PROFILER_STOP = 0x1902,
    /// The console stream on or off.
    PROFILER_LOG = 0x1903,
    /// The profiler where it lies: the reply is the address of READ's words (profiler.json) over the
    /// last `window_ms`, an infinite window being the whole recording, good until the next turn.
    PROFILER_READ = 0x1904,
    /// The rows the console stream kept: the reply is the address of LOG's words, and the rows are let go on the next turn.
    PROFILER_TAKE = 0x1905,
    /// The UI's snapshot, when it changed: a Snapshot packet far past a ring frame, so a
    /// block the kernel holds, valid until the next snapshot.
    WORLD_SNAPSHOT = 0x1004,
}

